CREATE TABLE app.def_child (
  id integer GENERATED ALWAYS AS IDENTITY NOT NULL,
  parent_id integer NOT NULL,
  qty integer DEFAULT 1 NOT NULL,
  label text DEFAULT 'n/a'::text,
  price numeric(10,2) DEFAULT 0.00,
  created timestamp with time zone DEFAULT now(),
  tags text[] DEFAULT '{}'::text[],
  slug text GENERATED ALWAYS AS (lower(label)) STORED
);

ALTER TABLE app.def_child ADD CONSTRAINT def_child_pkey PRIMARY KEY (id);

ALTER TABLE app.def_child ADD CONSTRAINT def_child_parent_id_label_key UNIQUE (parent_id, label);

ALTER TABLE app.def_child ADD CONSTRAINT def_child_qty_check CHECK (qty > 0);

ALTER TABLE app.def_child ADD CONSTRAINT qty_cap CHECK (qty < 1000);

ALTER TABLE app.def_child ADD CONSTRAINT def_child_parent_id_fkey FOREIGN KEY (parent_id) REFERENCES app.def_parent(id) ON DELETE CASCADE;

CREATE INDEX def_child_expr_idx ON app.def_child USING btree (lower(label));

CREATE INDEX def_child_label_idx ON app.def_child USING btree (label DESC);

CREATE INDEX def_child_part_idx ON app.def_child USING btree (qty) WHERE (qty > 10);

COMMENT ON TABLE app.def_child IS 'children';

COMMENT ON COLUMN app.def_child.label IS 'display label';

sqlite#copy:
CREATE TABLE def_child (
  id integer primary key autoincrement,
  parent_id integer not null references def_parent(id) on delete cascade,
  qty integer not null default 1 check (qty > 0),
  label text default 'n/a' collate nocase,
  price real default 0.5,
  slug text generated always as (lower(label)) stored,
  unique (parent_id, label),
  constraint qty_cap check (qty < 1000)
);

CREATE INDEX def_child_label_idx on def_child (label desc);

CREATE INDEX def_child_part_idx on def_child (qty) where qty > 10;

CREATE INDEX def_child_expr_idx on def_child (lower(label));
